sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    //Get attributes values from request
    var params = request.queryParams;
    var num = params.number;

    try {

        //Number value is mandatory
        if (num == '' || num == null) {

            var myError = new sn_ws_err.ServiceError();
            myError.setStatus(442);
            myError.setMessage('Number cannot be empty!');
            myError.setDetail('We recognized the number attribute you sent has no value. Complete the number and send the request again.');
            return myError;

        } else {

            var gr = new GlideRecord("incident");
            gr.addQuery('number', num);
            gr.query();

            if (gr.next()) {

                response.setContentType('application/json');
                response.setBody({
                    Result: "The Incident hes been found",
                    Number: gr.number,
                    Short_description: gr.short_description,
                    Priority: gr.priority,
                    Assigment_group: gr.assignment_group,
                    Assigned_to: gr.assigned_to,
                });

                response.setStatus(200);
            }
			else {
/*				var notFoundError = new sn_ws_err.ServiceError();
				notFoundError.setStatus(404);
				notFoundError.setMessage('Incident with number ' + num + ' has not been found');
				notFoundError.setDetail('Incident number does not exist');
				return notFoundError;
				*/

				response.setError(new sn_ws_err.NotFoundError('Incident ' + num + ' was not found'));
				return;
			}

        }

    } catch (err) {
        var exp = new sn_ws_err.BadRequestError(err);
        response.setError(exp);
    }

})(request, response);
